  'tc.takesSeconds':     { IT: 'Ci vogliono 15-30 secondi.', EN: 'It takes 15-30 seconds.', FR: 'Cela prend 15 à 30 secondes.', DE: 'Es dauert 15-30 Sekunden.', ES: 'Tarda entre 15 y 30 segundos.', PT: 'Leva de 15 a 30 segundos.' },
  'tc.mainTitle':        { IT: "CV su misura per l'offerta", EN: 'CV tailored to the job posting', FR: 'CV sur mesure pour l\'offre', DE: 'Auf die Stelle zugeschnittener Lebenslauf', ES: 'CV a medida para la oferta', PT: 'CV sob medida para a vaga' },
  'tc.mainSub':          { IT: "Incolla il testo o l'URL dell'offerta di lavoro. L'AI selezionerà le tue esperienze più rilevanti, le riscriverà con le keyword richieste e genererà un CV ottimizzato.", EN: 'Paste the text or the URL of the job posting. The AI will select your most relevant experiences, rewrite them with the required keywords, and generate an optimized CV.', FR: "Collez le texte ou l'URL de l'offre d'emploi. L'IA sélectionnera vos expériences les plus pertinentes, les réécrira avec les mots-clés requis et générera un CV optimisé.", DE: 'Fügen Sie den Text oder die URL der Stellenanzeige ein. Die KI wählt Ihre relevantesten Erfahrungen aus, formuliert sie mit den erforderlichen Keywords um und erstellt einen optimierten Lebenslauf.', ES: 'Pega el texto o la URL de la oferta de trabajo. La IA seleccionará tus experiencias más relevantes, las reescribirá con las palabras clave requeridas y generará un CV optimizado.', PT: 'Cole o texto ou a URL da vaga de emprego. A IA selecionará suas experiências mais relevantes, as reescreverá com as palavras-chave exigidas e gerará um CV otimizado.' },
  'tc.loginGate':        { IT: 'Accedi per creare il tuo CV su misura', EN: 'Sign in to create your tailored CV', FR: 'Connectez-vous pour créer votre CV sur mesure', DE: 'Anmelden, um Ihren maßgeschneiderten Lebenslauf zu erstellen', ES: 'Inicia sesión para crear tu CV a medida', PT: 'Entre para criar seu CV sob medida' },
  'tc.loginGateSub':     { IT: "L'AI usa le esperienze salvate nel tuo archivio personale. Accedi per continuare.", EN: 'The AI uses the experiences saved in your personal archive. Sign in to continue.', FR: "L'IA utilise les expériences enregistrées dans vos archives personnelles. Connectez-vous pour continuer.", DE: 'Die KI verwendet die in Ihrem persönlichen Archiv gespeicherten Erfahrungen. Melden Sie sich an, um fortzufahren.', ES: 'La IA usa las experiencias guardadas en tu archivo personal. Inicia sesión para continuar.', PT: 'A IA usa as experiências salvas no seu arquivo pessoal. Entre para continuar.' },
  'tc.tabUrl':           { IT: "🔗 Incolla l'URL dell'offerta", EN: '🔗 Paste the posting URL', FR: "🔗 Collez l'URL de l'offre", DE: '🔗 URL der Anzeige einfügen', ES: '🔗 Pega la URL de la oferta', PT: '🔗 Cole a URL da vaga' },
