  'wiz.pasteLinkedinPlaceholder': { IT: 'Incolla qui tutto il testo del tuo profilo o della sezione Esperienze (es. copiatutto da LinkedIn con CTRL+A e incolla qui)...', EN: 'Paste here the full text of your profile or Experience section (e.g. select all on LinkedIn with CTRL+A and paste here)...', FR: 'Collez ici tout le texte de votre profil ou de la section Expériences (ex. sélectionnez tout sur LinkedIn avec CTRL+A et collez ici)...', DE: 'Fügen Sie hier den gesamten Text Ihres Profils oder des Abschnitts Erfahrungen ein (z.B. alles auf LinkedIn mit STRG+A auswählen und hier einfügen)...', ES: 'Pega aquí todo el texto de tu perfil o de la sección Experiencia (ej. selecciona todo en LinkedIn con CTRL+A y pégalo aquí)...', PT: 'Cole aqui todo o texto do seu perfil ou da seção Experiências (ex. selecione tudo no LinkedIn com CTRL+A e cole aqui)...' },
  'wiz.pasteLinkedinHint': { IT: "💡 Puoi copiare direttamente l'intero testo della tua pagina LinkedIn: l'Intelligenza Artificiale filtrerà ed estrarrà solo ruoli, date e competenze.", EN: '💡 You can copy the entire text of your LinkedIn page directly: the AI will filter and extract only roles, dates and skills.', FR: "💡 Vous pouvez copier directement tout le texte de votre page LinkedIn : l'IA filtrera et extraira uniquement les postes, dates et compétences.", DE: '💡 Sie können den gesamten Text Ihrer LinkedIn-Seite direkt kopieren: Die KI filtert und extrahiert nur Rollen, Daten und Fähigkeiten.', ES: '💡 Puedes copiar directamente todo el texto de tu página de LinkedIn: la IA filtrará y extraerá solo roles, fechas y habilidades.', PT: '💡 Você pode copiar diretamente todo o texto da sua página do LinkedIn: a IA filtrará e extrairá apenas funções, datas e habilidades.' },
  'wiz.fileUploadedHint': { IT: 'File caricato · clicca per cambiarlo', EN: 'File uploaded · click to change it', FR: 'Fichier téléchargé · cliquez pour le changer', DE: 'Datei hochgeladen · zum Ändern klicken', ES: 'Archivo subido · haz clic para cambiarlo', PT: 'Arquivo enviado · clique para alterá-lo' },
  'wiz.dragLinkedinPdf': { IT: 'Trascina il PDF esportato da LinkedIn', EN: 'Drag the PDF exported from LinkedIn', FR: 'Glissez le PDF exporté de LinkedIn', DE: 'Das von LinkedIn exportierte PDF ziehen', ES: 'Arrastra el PDF exportado de LinkedIn', PT: 'Arraste o PDF exportado do LinkedIn' },
