  'wiz.dragLinkedinPdfHint': { IT: 'Da LinkedIn: Il tuo profilo → Altro → Salva come PDF', EN: 'From LinkedIn: Your profile → More → Save as PDF', FR: 'Depuis LinkedIn : Votre profil → Plus → Enregistrer au format PDF', DE: 'Von LinkedIn: Ihr Profil → Mehr → Als PDF speichern', ES: 'Desde LinkedIn: Tu perfil → Más → Guardar como PDF', PT: 'Do LinkedIn: Seu perfil → Mais → Salvar como PDF' },
  'wiz.orClickToSelect': { IT: 'o clicca per selezionarlo — PDF o Word', EN: 'or click to select it — PDF or Word', FR: 'ou cliquez pour le sélectionner — PDF ou Word', DE: 'oder klicken Sie zum Auswählen — PDF oder Word', ES: 'o haz clic para seleccionarlo — PDF o Word', PT: 'ou clique para selecioná-lo — PDF ou Word' },
