  'wiz.whichLanguage':   { IT: 'In che lingua vuoi il tuo CV?', EN: 'What language do you want your CV in?', FR: 'Dans quelle langue voulez-vous votre CV ?', DE: 'In welcher Sprache möchten Sie Ihren Lebenslauf?', ES: '¿En qué idioma quieres tu CV?', PT: 'Em que idioma você quer seu CV?' },
  'wiz.whichLanguageSub': { IT: 'Potrai comunque tradurlo o modificarlo in qualsiasi momento dall\'editor.', EN: 'You can still translate or edit it at any time from the editor.', FR: "Vous pourrez toujours le traduire ou le modifier à tout moment depuis l'éditeur.", DE: 'Sie können ihn jederzeit im Editor übersetzen oder bearbeiten.', ES: 'De todas formas podrás traducirlo o modificarlo en cualquier momento desde el editor.', PT: 'De qualquer forma, você pode traduzi-lo ou editá-lo a qualquer momento no editor.' },
