  'wiz.chooseTemplate':  { IT: 'Scegli il template', EN: 'Choose a template', FR: 'Choisissez un modèle', DE: 'Vorlage wählen', ES: 'Elige una plantilla', PT: 'Escolha um modelo' },
  'wiz.chooseTemplateSub': { IT: 'Anteprime reali — tutti ottimizzati ATS per il mercato italiano ed europeo.', EN: 'Real previews — all optimized for ATS for the Italian and European market.', FR: 'Aperçus réels — tous optimisés ATS pour le marché italien et européen.', DE: 'Echte Vorschauen — alle ATS-optimiert für den italienischen und europäischen Markt.', ES: 'Vistas previas reales — todas optimizadas para ATS en el mercado italiano y europeo.', PT: 'Pré-visualizações reais — todos otimizados para ATS para o mercado italiano e europeu.' },
