  'pz.freeDesc': { IT: 'Per provare la piattaforma senza impegno.', EN: 'To try the platform with no commitment.', FR: 'Pour essayer la plateforme sans engagement.', DE: 'Um die Plattform unverbindlich zu testen.', ES: 'Para probar la plataforma sin compromiso.', PT: 'Para experimentar a plataforma sem compromisso.' },
